{
  "provider": "{{localProvider}}",
  "maxTokens": 40,
  "messages": [
    {
      "role": "user",
      "content": "Quelle est la capitale de la Mauritanie ?"
    }
  ]
}

{
  "provider": "{{localProvider}}",
  "temperature": 0.2,
  "maxTokens": 40,
  "messages": [
    {
      "role": "system",
      "content": "Tu reponds en une seule phrase courte, en francais."
    },
    {
      "role": "user",
      "content": "A quoi sert un fichier VTT ?"
    }
  ]
}

{
  "provider": "{{localProvider}}",
  "maxTokens": 200,
  "messages": [
    {
      "role": "user",
      "content": "Analyse : le job de transcodage 4412 a echoue apres 3 tentatives, la file SQS est a 8200 messages."
    }
  ],
  "schema": {
    "type": "object",
    "required": [
      "jobId",
      "status",
      "severity",
      "queueDepth"
    ],
    "additionalProperties": false,
    "properties": {
      "jobId": {
        "type": "integer"
      },
      "status": {
        "type": "string",
        "enum": [
          "PENDING",
          "RUNNING",
          "DONE",
          "FAILED"
        ]
      },
      "severity": {
        "type": "string",
        "enum": [
          "low",
          "medium",
          "high",
          "critical"
        ]
      },
      "queueDepth": {
        "type": "integer",
        "minimum": 0
      }
    }
  }
}

{
  "provider": "{{localProvider}}",
  "maxTokens": 400,
  "messages": [
    {
      "role": "user",
      "content": "Les pods de transcodage redemarrent en boucle depuis 10 minutes (CrashLoopBackOff). La file SQS monte a 12000 messages. Le dernier deploiement date de 15 minutes."
    }
  ],
  "schema": {
    "type": "object",
    "required": [
      "symptom",
      "observations",
      "hypotheses",
      "probableCause",
      "recommendedAction",
      "severity"
    ],
    "additionalProperties": false,
    "properties": {
      "symptom": {
        "type": "string"
      },
      "observations": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "hypotheses": {
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "probableCause": {
        "type": "string"
      },
      "recommendedAction": {
        "type": "string"
      },
      "severity": {
        "type": "string",
        "enum": [
          "low",
          "medium",
          "high",
          "critical"
        ]
      }
    }
  }
}
